<?php use App\Models\Content;use App\Services\Navigation;use App\Services\Settings;
$utility=static fn(string $key,string $fallback):string=>Settings::has($key)?setting($key):$fallback;
$utilityCompany=$utility('utility_company_label',setting('company_name'));
$utilityTagline=$utility('utility_tagline','Excellence in Logistics');
$utilityLocation=$utility('utility_location','India · Global Reach');
$utilityPhone=$utility('utility_phone','9995694138');
$utilityEmail=$utility('utility_email','globaltradelines.gtr@gmail.com');
$utilitySocials=array_values(array_filter([
    ['LinkedIn','fa-brands fa-linkedin-in',$utility('linkedin_url','https://www.linkedin.com/')],
    ['Instagram','fa-brands fa-instagram',$utility('instagram_url','https://www.instagram.com/')],
    ['WhatsApp','fa-brands fa-whatsapp',$utility('whatsapp_url','https://wa.me/919995694138')],
    ['Facebook','fa-brands fa-facebook-f',$utility('facebook_url','https://www.facebook.com/')],
],static fn(array $social):bool=>$social[2]!==''));
?>
<div id="siteHeaderGroup"><div class="topbar-pro"><div class="container"><div class="tb-left"><?php if($utilityCompany):?><span class="tb-company"><?=e($utilityCompany)?></span><?php endif?><?php if($utilityCompany&&$utilityTagline):?><span class="tb-divider tb-left-divider"></span><?php endif?><?php if($utilityTagline):?><span class="tb-tagline"><?=e($utilityTagline)?></span><?php endif?><?php if(($utilityCompany||$utilityTagline)&&$utilityLocation):?><span class="tb-divider tb-left-divider"></span><?php endif?><?php if($utilityLocation):?><span class="tb-location"><i class="fa-solid fa-location-dot" aria-hidden="true"></i> <?=e($utilityLocation)?></span><?php endif?></div><div class="tb-right"><?php if($utilityPhone):?><a href="tel:<?=e(preg_replace('/[^+0-9]/','',$utilityPhone))?>"><i class="fa-solid fa-phone" aria-hidden="true"></i><span><?=e($utilityPhone)?></span></a><?php endif?><?php if($utilityPhone&&($utilityEmail||$utilitySocials)):?><span class="tb-divider"></span><?php endif?><?php if($utilityEmail):?><a href="mailto:<?=e($utilityEmail)?>"><i class="fa-regular fa-envelope" aria-hidden="true"></i><span><?=e($utilityEmail)?></span></a><?php endif?><?php if($utilityEmail&&$utilitySocials):?><span class="tb-divider tb-social-divider"></span><?php endif?><?php if($utilitySocials):?><div class="tb-social"><?php foreach($utilitySocials as [$label,$icon,$url]):?><a href="<?=e($url)?>" aria-label="<?=e($label)?>" target="_blank" rel="noopener noreferrer"><i class="<?=e($icon)?>" aria-hidden="true"></i></a><?php endforeach?></div><?php endif?></div></div></div></div>
<header class="main-header" id="siteHeader"><div class="nav-wrap"><a class="brand" href="<?=e(cms_url(setting('logo_link','/')))?>"><?php if(setting('header_logo')):?><?=media_img(setting('header_logo'),setting('company_name'),'site-header-logo',false)?><?php else:?><h1><?=e(setting('company_name'))?></h1><?php endif?><?php if(setting('alternate_logo')):?><?=media_img(setting('alternate_logo'),setting('company_name'),'cms-alternate-logo',false)?><?php endif?></a><nav class="primary-nav <?=setting('mobile_navigation')==='expanded'?'cms-mobile-expanded':''?>" aria-label="<?=text('main_navigation')?>"><ul><?php foreach(Content::published('navigation_menus',"location='header'") as $menu){$items=Content::published('navigation_items','menu_id=?',[$menu['id']]);Navigation::renderItems($items);}?></ul></nav><div class="nav-actions"><?php if(setting('search_visible')==='1'):?><button class="cms-search-button" id="searchOpen" type="button" aria-label="<?=text('search')?>"><i class="fa-solid fa-magnifying-glass"></i></button><?php endif?><?php if(setting('product_search')==='1'):?><a class="nav-product-search" data-search-template="<?=text('search_template')?>" href="<?=e(cms_url('/products/#product-search'))?>" aria-label="<?=text('product_search')?>"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><span class="nav-search-placeholder"><?=text('product_search')?></span><span class="nav-search-terms" hidden><?php foreach(Content::published('categories','1=1',[],10) as $category):?><span data-nav-search-term><?=e($category['title'])?></span><?php endforeach?></span></a><?php endif?><?php if(setting('cta_label')):?><a href="<?=e(cms_url(setting('cta_url')))?>" class="btn btn-primary"><?=e(setting('cta_label'))?></a><?php endif?><button class="menu-toggle" id="menuToggle" aria-label="<?=text('toggle_menu')?>" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12h18M3 6h18M3 18h18"/></svg></button></div></div></header></div>
